class Solution:
    def numberOfArithmeticSlices(self, nums: list[int]) -> int:
        total = 0
        for left in range(len(nums) - 2):
            difference = nums[left + 1] - nums[left]
            for right in range(left + 2, len(nums)):
                if nums[right] - nums[right - 1] != difference:
                    break
                total += 1
        return total
